-- PostgreSQL 16 DDL draft; use Alembic in implementation. All IDs supplied by service.
BEGIN;
CREATE TABLE data_source(id uuid PRIMARY KEY, name text NOT NULL, platform text NOT NULL, permission_scope text NOT NULL, expires_at timestamptz, enabled boolean NOT NULL DEFAULT true, is_demo boolean NOT NULL DEFAULT false);
CREATE TABLE import_batch(id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES data_source, file_sha256 text NOT NULL, mapping_version text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), accepted int NOT NULL DEFAULT 0 CHECK(accepted>=0), rejected int NOT NULL DEFAULT 0 CHECK(rejected>=0), UNIQUE(source_id,file_sha256,mapping_version));
CREATE TABLE evidence(id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES data_source, batch_id uuid REFERENCES import_batch, locator text NOT NULL, content_hash text, observed_at timestamptz NOT NULL, expires_at timestamptz, quality_flag text NOT NULL CHECK(quality_flag IN ('valid','stale','conflict','missing','rejected')), metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE keyword_snapshot(id uuid PRIMARY KEY, evidence_id uuid NOT NULL REFERENCES evidence, source_id uuid NOT NULL REFERENCES data_source, category text NOT NULL, keyword text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, observed_at timestamptz NOT NULL, search_index numeric CHECK(search_index>=0), listing_count bigint CHECK(listing_count>=0), conversion numeric CHECK(conversion BETWEEN 0 AND 1), mall_click_share numeric CHECK(mall_click_share BETWEEN 0 AND 1), metric_definition text NOT NULL, revision int NOT NULL DEFAULT 1 CHECK(revision>0), CHECK(window_end>window_start), UNIQUE(source_id,category,keyword,window_start,window_end,metric_definition,revision));
CREATE INDEX keyword_lookup ON keyword_snapshot(category,keyword,window_end DESC);
CREATE TABLE product(id uuid PRIMARY KEY, name text NOT NULL, category text NOT NULL, brand text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE canonical_sku(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES product, spec_key text NOT NULL, attributes jsonb NOT NULL, quantity int NOT NULL CHECK(quantity>0), UNIQUE(product_id,spec_key));
CREATE TABLE listing(id uuid PRIMARY KEY, platform text NOT NULL, external_id text NOT NULL, title text NOT NULL, url text, UNIQUE(platform,external_id));
CREATE TABLE listing_sku(id uuid PRIMARY KEY, listing_id uuid NOT NULL REFERENCES listing, external_sku_id text NOT NULL, attributes jsonb NOT NULL DEFAULT '{}', UNIQUE(listing_id,external_sku_id));
CREATE TABLE sku_match(id uuid PRIMARY KEY, listing_sku_id uuid NOT NULL REFERENCES listing_sku, canonical_sku_id uuid NOT NULL REFERENCES canonical_sku, state text NOT NULL CHECK(state IN ('PENDING','MATCHED','REJECTED','ALTERNATIVE')), score numeric CHECK(score BETWEEN 0 AND 100), reviewed_by text, reviewed_at timestamptz, evidence_id uuid REFERENCES evidence, reason text NOT NULL, UNIQUE(listing_sku_id,canonical_sku_id));
CREATE UNIQUE INDEX match_single_confirmed ON sku_match(listing_sku_id) WHERE state='MATCHED';
CREATE TABLE price_snapshot(id uuid PRIMARY KEY, listing_sku_id uuid NOT NULL REFERENCES listing_sku, evidence_id uuid NOT NULL REFERENCES evidence, observed_at timestamptz NOT NULL, price_kind text NOT NULL CHECK(price_kind IN ('LIST','ELIGIBLE','DROPSHIP','WHOLESALE')), currency char(3) NOT NULL DEFAULT 'CNY', region text NOT NULL, quantity int NOT NULL CHECK(quantity>0), price numeric(18,4) CHECK(price>=0), shipping numeric(18,4) CHECK(shipping>=0), conditions jsonb NOT NULL DEFAULT '{}', UNIQUE(listing_sku_id,evidence_id,price_kind,region,quantity));
CREATE INDEX price_lookup ON price_snapshot(listing_sku_id,observed_at DESC);
CREATE TABLE metric_observation(id uuid PRIMARY KEY, listing_id uuid NOT NULL REFERENCES listing, evidence_id uuid NOT NULL REFERENCES evidence, metric_kind text NOT NULL, unit text NOT NULL, raw_value text NOT NULL, parsed_value numeric, upper_value numeric, precision text NOT NULL CHECK(precision IN ('exact','lower_bound','range','estimate','unknown')), window_start timestamptz, window_end timestamptz, CHECK(window_start IS NULL OR window_end IS NULL OR window_end>window_start), UNIQUE(listing_id,evidence_id,metric_kind,unit));
CREATE TABLE supplier(id uuid PRIMARY KEY, platform text NOT NULL DEFAULT '1688', external_id text NOT NULL, name text NOT NULL, status text NOT NULL, UNIQUE(platform,external_id));
CREATE TABLE supplier_offer(id uuid PRIMARY KEY, supplier_id uuid NOT NULL REFERENCES supplier, canonical_sku_id uuid NOT NULL REFERENCES canonical_sku, evidence_id uuid NOT NULL REFERENCES evidence, dropship boolean, quantity int NOT NULL CHECK(quantity>0), unit_cost numeric(18,4) CHECK(unit_cost>=0), shipping numeric(18,4) CHECK(shipping>=0), service_fee numeric(18,4) CHECK(service_fee>=0), region text NOT NULL, lead_hours int CHECK(lead_hours>=0), expires_at timestamptz, return_terms jsonb NOT NULL DEFAULT '{}', UNIQUE(supplier_id,canonical_sku_id,evidence_id,region,quantity));
CREATE TABLE sample_check(id uuid PRIMARY KEY, offer_id uuid NOT NULL REFERENCES supplier_offer, result text NOT NULL CHECK(result IN ('PENDING','PASSED','FAILED')), evidence_id uuid REFERENCES evidence, reviewer text, checked_at timestamptz, details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE strategy_version(id uuid PRIMARY KEY, version text UNIQUE NOT NULL, config jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE candidate(id uuid PRIMARY KEY, canonical_sku_id uuid NOT NULL REFERENCES canonical_sku, state text NOT NULL CHECK(state IN ('DISCOVERED','RESEARCHING','READY_SAMPLE','SAMPLE_PASSED','READY_TEST','TESTING','SCALE','HOLD','REJECTED','ARCHIVED')), version int NOT NULL DEFAULT 1 CHECK(version>0), primary_offer_id uuid REFERENCES supplier_offer, backup_offer_id uuid REFERENCES supplier_offer, created_at timestamptz NOT NULL DEFAULT now(), CHECK(primary_offer_id IS NULL OR backup_offer_id IS NULL OR primary_offer_id<>backup_offer_id));
CREATE TABLE score_run(id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES candidate, strategy_id uuid NOT NULL REFERENCES strategy_version, input_snapshot jsonb NOT NULL, factor_scores jsonb NOT NULL, input_hash text NOT NULL, coverage numeric NOT NULL CHECK(coverage BETWEEN 0 AND 1), score numeric CHECK(score BETWEEN 0 AND 100), score_low numeric CHECK(score_low BETWEEN 0 AND 100), score_high numeric CHECK(score_high BETWEEN 0 AND 100), grade text CHECK(grade IN ('S','A','B','C','D')), gate text NOT NULL CHECK(gate IN ('PASS','BLOCKED','NEEDS_EVIDENCE')), confidence text NOT NULL CHECK(confidence IN ('LOW','MEDIUM','HIGH')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(score_low IS NULL OR score_high IS NULL OR score_high>=score_low), CHECK(grade IS NULL OR (coverage=1 AND score IS NOT NULL AND gate='PASS')), UNIQUE(candidate_id,strategy_id,input_hash));
CREATE TABLE profit_scenario(id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES candidate, label text NOT NULL, inputs jsonb NOT NULL, contribution numeric(18,4) NOT NULL, max_cac numeric(18,4) NOT NULL, input_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_id,label,input_hash));
CREATE TABLE risk_review(id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES candidate, risk_code text NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','PASS','BLOCKED')), evidence_id uuid REFERENCES evidence, reviewer text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE experiment(id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES candidate, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, budget numeric(18,4) NOT NULL CHECK(budget>=0), status text NOT NULL, hypothesis text NOT NULL, score_run_id uuid REFERENCES score_run, CHECK(end_at>start_at));
CREATE TABLE funnel_daily(id uuid PRIMARY KEY, experiment_id uuid NOT NULL REFERENCES experiment, business_date date NOT NULL, channel text NOT NULL, impressions bigint CHECK(impressions>=0), clicks bigint CHECK(clicks>=0), paid_orders bigint CHECK(paid_orders>=0), ad_spend numeric(18,4) CHECK(ad_spend>=0), evidence_id uuid NOT NULL REFERENCES evidence, UNIQUE(experiment_id,business_date,channel));
CREATE TABLE order_ledger(id uuid PRIMARY KEY, experiment_id uuid NOT NULL REFERENCES experiment, order_key_hash text NOT NULL, paid_at timestamptz NOT NULL, revenue numeric(18,4) NOT NULL CHECK(revenue>=0), customer_refund numeric(18,4) NOT NULL DEFAULT 0 CHECK(customer_refund>=0), purchase numeric(18,4) NOT NULL DEFAULT 0 CHECK(purchase>=0), purchase_refund numeric(18,4) NOT NULL DEFAULT 0 CHECK(purchase_refund>=0), shipping numeric(18,4) NOT NULL DEFAULT 0 CHECK(shipping>=0), packaging numeric(18,4) NOT NULL DEFAULT 0 CHECK(packaging>=0), net_fees numeric(18,4) NOT NULL DEFAULT 0, advertising numeric(18,4) NOT NULL DEFAULT 0 CHECK(advertising>=0), other_net_cost numeric(18,4) NOT NULL DEFAULT 0, mature boolean NOT NULL DEFAULT false, evidence_id uuid NOT NULL REFERENCES evidence, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(experiment_id,order_key_hash));
CREATE TABLE ai_report(id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES candidate, input_hash text NOT NULL, model_version text NOT NULL, prompt_version text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_id,input_hash,model_version,prompt_version));
CREATE TABLE job(id uuid PRIMARY KEY, kind text NOT NULL, idem_key text NOT NULL, payload jsonb NOT NULL, status text NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')), attempts int NOT NULL DEFAULT 0 CHECK(attempts>=0), run_after timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, result jsonb, error_code text, UNIQUE(kind,idem_key));
CREATE INDEX job_claim ON job(status,run_after);
CREATE TABLE audit_event(id uuid PRIMARY KEY, actor text NOT NULL, action text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
